const fieldKey = "deal_00000000-0000-0000-0000-000000000001";

const entradas = $input.all();

const negocios = entradas.flatMap(item => {
  const dados = item.json;

  if (Array.isArray(dados)) {
    return dados.flatMap(x => x.value || []);
  }

  if (Array.isArray(dados.value)) {
    return dados.value;
  }

  return dados.Id ? [dados] : [];
});

const resultado = [];

for (const negocio of negocios) {
  const campo = (negocio.OtherProperties || [])
    .find(prop => prop.FieldKey === fieldKey);

  const solicitacao = String(
    campo?.BigStringValue ??
    campo?.StringValue ??
    ""
  ).trim();

  // Ignorar pedidos sem solicitação
  if (!solicitacao) continue;

  resultado.push({
    json: {
      negocioId: negocio.Id,
      titulo: negocio.Title,
      etapaId: negocio.StageId,
      solicitacao,
      tamanhoSolicitacao: solicitacao.length
    }
  });
}

return resultado;

const pedidos = $('Preparar Dados IA').all()
  .map(item => item.json);

const registros = $input.all()
  .map(item => item.json)
  .filter(item => item.negocioId != null);

const historico = new Map(
  registros.map(item => [
    String(item.negocioId),
    item.solicitacaoAnterior || ""
  ])
);

const resultado = [];

for (const pedido of pedidos) {
  const id = String(pedido.negocioId);
  const anterior = historico.get(id);

  let situacao;

  if (anterior === undefined) {
    situacao = "NOVO";
  } else if (anterior !== pedido.solicitacao) {
    situacao = "ALTERADO";
  } else {
    situacao = "SEM ALTERACAO";
  }

  if (situacao === "SEM ALTERACAO") {
    continue;
  }

  resultado.push({
    json: {
      ...pedido,
      situacao,
      precisaAnalise: true
    }
  });
}

return resultado;
